1486	    if (input.apiBaseUrl) {
1487	      base = new URL(input.apiBaseUrl);
1488	    }
1489	  } catch {
1490	    base = null;
1491	  }
1492	
1493	  const protocol = base?.protocol ?? "http:";
1494	  const port = base?.port ? `:${base.port}` : "";
1495	  const candidates = new Set<string>();
1496	
1497	  if (base) {
1498	    candidates.add(base.origin);
1499	  }
1500	
1501	  const bindHost = normalizeHostname(input.bindHost);
1502	  if (bindHost && !isLoopbackHost(bindHost)) {
1503	    candidates.add(`${protocol}//${bindHost}${port}`);
1504	  }
1505	
1506	  for (const rawHost of input.allowedHostnames) {
1507	    const host = normalizeHostname(rawHost);
1508	    if (!host) continue;
1509	    candidates.add(`${protocol}//${host}${port}`);
1510	  }
1511	
1512	  if (base && isLoopbackHost(base.hostname)) {
1513	    candidates.add(`${protocol}//host.docker.internal${port}`);
